"""
Task 010 — Simple filter expression evaluator

Implements evaluate(expr, record) -> bool
"""

import re


# ---------------------------------------------------------------------------
# Tokeniser
# ---------------------------------------------------------------------------

# Token types
TK_AND    = 'AND'
TK_OR     = 'OR'
TK_NOT    = 'NOT'
TK_LPAREN = 'LPAREN'
TK_RPAREN = 'RPAREN'
TK_OP     = 'OP'
TK_IDENT  = 'IDENT'
TK_NUMBER = 'NUMBER'
TK_STRING = 'STRING'
TK_EOF    = 'EOF'

# Regex patterns (order matters)
_TOKEN_PATTERNS = [
    (TK_NUMBER,  r'-?(?:\d+\.\d*|\.\d+|\d+)'),
    (TK_STRING,  r"'[^']*'"),
    (TK_OP,      r'>=|<=|!=|==|>|<'),
    (TK_LPAREN,  r'\('),
    (TK_RPAREN,  r'\)'),
    (TK_IDENT,   r'[A-Za-z_][A-Za-z0-9_]*'),
]

_TOKEN_RE = re.compile(
    '|'.join(f'(?P<{name}>{pat})' for name, pat in _TOKEN_PATTERNS)
)


def _tokenise(text: str):
    """Return list of (type, value) tokens, ignoring whitespace."""
    tokens = []
    pos = 0
    while pos < len(text):
        # skip whitespace
        if text[pos].isspace():
            pos += 1
            continue
        m = _TOKEN_RE.match(text, pos)
        if m is None:
            raise ValueError(f"Unexpected character {text[pos]!r} at position {pos}")
        kind = m.lastgroup
        val  = m.group()
        # Reclassify keywords
        if kind == TK_IDENT and val == 'AND':
            kind = TK_AND
        elif kind == TK_IDENT and val == 'OR':
            kind = TK_OR
        elif kind == TK_IDENT and val == 'NOT':
            kind = TK_NOT
        tokens.append((kind, val))
        pos = m.end()
    tokens.append((TK_EOF, ''))
    return tokens


# ---------------------------------------------------------------------------
# Parser (recursive descent)
# ---------------------------------------------------------------------------

class _Parser:
    def __init__(self, tokens):
        self._tokens = tokens
        self._pos    = 0

    def _peek(self):
        return self._tokens[self._pos]

    def _consume(self, expected_type=None):
        kind, val = self._tokens[self._pos]
        if expected_type and kind != expected_type:
            raise ValueError(
                f"Expected {expected_type} but got {kind!r} ({val!r})"
            )
        self._pos += 1
        return kind, val

    # -- grammar productions -------------------------------------------------

    def parse_expr(self):
        node = self._parse_or()
        if self._peek()[0] != TK_EOF:
            raise ValueError(
                f"Unexpected token {self._peek()[1]!r} after expression"
            )
        return node

    def _parse_or(self):
        left = self._parse_and()
        while self._peek()[0] == TK_OR:
            self._consume(TK_OR)
            right = self._parse_and()
            left  = ('or', left, right)
        return left

    def _parse_and(self):
        left = self._parse_not()
        while self._peek()[0] == TK_AND:
            self._consume(TK_AND)
            right = self._parse_not()
            left  = ('and', left, right)
        return left

    def _parse_not(self):
        if self._peek()[0] == TK_NOT:
            self._consume(TK_NOT)
            operand = self._parse_not()
            return ('not', operand)
        return self._parse_comparison()

    def _parse_comparison(self):
        if self._peek()[0] == TK_LPAREN:
            self._consume(TK_LPAREN)
            node = self._parse_or()
            if self._peek()[0] != TK_RPAREN:
                raise ValueError("Unmatched '(' — missing closing ')'")
            self._consume(TK_RPAREN)
            return node

        # field op value
        kind, field_name = self._peek()
        if kind != TK_IDENT:
            raise ValueError(
                f"Expected field name (identifier) but got {kind!r} ({field_name!r})"
            )
        self._consume(TK_IDENT)

        kind, op = self._peek()
        if kind != TK_OP:
            raise ValueError(
                f"Expected comparison operator but got {kind!r} ({op!r})"
            )
        self._consume(TK_OP)

        kind, raw_val = self._peek()
        if kind == TK_NUMBER:
            self._consume(TK_NUMBER)
            # parse as int or float
            try:
                if '.' in raw_val:
                    value = float(raw_val)
                else:
                    value = int(raw_val)
            except ValueError:
                value = float(raw_val)
        elif kind == TK_STRING:
            self._consume(TK_STRING)
            value = raw_val[1:-1]  # strip surrounding quotes
        else:
            raise ValueError(
                f"Expected number or quoted string as value but got {kind!r} ({raw_val!r})"
            )

        return ('cmp', field_name, op, value)


# ---------------------------------------------------------------------------
# Evaluator
# ---------------------------------------------------------------------------

def _eval_node(node, record: dict) -> bool:
    tag = node[0]

    if tag == 'or':
        _, left, right = node
        return _eval_node(left, record) or _eval_node(right, record)

    if tag == 'and':
        _, left, right = node
        return _eval_node(left, record) and _eval_node(right, record)

    if tag == 'not':
        _, operand = node
        return not _eval_node(operand, record)

    if tag == 'cmp':
        _, field, op, value = node
        if field not in record:
            raise KeyError(field)
        field_val = record[field]

        # Type check
        both_numeric = isinstance(field_val, (int, float)) and isinstance(value, (int, float))
        both_string  = isinstance(field_val, str) and isinstance(value, str)
        if not (both_numeric or both_string):
            raise TypeError(
                f"Cannot compare {type(field_val).__name__!r} with {type(value).__name__!r}"
            )

        if op == '==':
            return field_val == value
        if op == '!=':
            return field_val != value
        if op == '>':
            return field_val > value
        if op == '<':
            return field_val < value
        if op == '>=':
            return field_val >= value
        if op == '<=':
            return field_val <= value
        raise ValueError(f"Unknown operator: {op!r}")

    raise ValueError(f"Unknown AST node tag: {tag!r}")


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def evaluate(expr: str, record: dict) -> bool:
    """
    Parse and evaluate a simple filter expression against a record dict.

    Returns True if the record matches the expression.

    Raises:
        ValueError  — on syntax errors
        KeyError    — if a referenced field is missing from record
        TypeError   — if comparison operands have incompatible types
    """
    tokens = _tokenise(expr)
    parser = _Parser(tokens)
    ast    = parser.parse_expr()
    return _eval_node(ast, record)
